def kernel_page(kernel, origin, owner='UA'):
    actor = turn(kernel.service, owner)
    with scope(actor):
        record = kernel.cloud.prepare(actor)
    supervisor = kernel.registry.get(record['session_key'])
    supervisor.origin = origin
    return actor, supervisor


def test_missing_personal_details_keep_available_owner_fields_for_reuse(service):
    PersonalStore(service.private_home('TT','UA')).save('address', ADDRESS)
    PersonalStore(service.private_home('TT','UB')).save('phone', PHONE)
    for owner, missing, available in [('UA', ['phone'], ['address']), ('UB', ['address'], ['phone']), ('UA', ['phone'], ['address'])]:
        result = service.personal.fill(turn(service, owner), origin='https://shop.example', fields=['address', 'phone'])
        assert result['status'] == 'personal_info_needed'
        assert result['missing'] == missing
        assert result['available_fields'] == available
        assert result['vault_url'] == service.config['public_url'].rstrip('/') + '/vault'
        assert all(value not in json.dumps(result) for value in (*ADDRESS.values(), '9876543210'))


