@pytest.mark.parametrize('country_code', [None, '+91'])
@pytest.mark.parametrize('parent_text,selected,accepted', [
    ('+91 Phone number', '', True),
    ('+91 Phone number +91', '', True),
    ('Phone number', 'India +91', True),
    ('Phone number', '', False),
    ('+1 Phone number', '', False),
