    ('+9191 Phone number', '', False),
])
def test_native_personal_fill_observes_calling_code_with_real_js(
        service, kernel, monkeypatch, tmp_path, country_code, parent_text, selected, accepted):
    """Run the emitted context JS, rather than supplying a precomputed code."""
    from tools import browser_vault_tool as native
    node = shutil.which('node')
    if not node:
        pytest.skip('Node.js is required to execute the calling-code DOM fixture')
    script = tmp_path / 'phone-context.js'
    script.write_text('''const fs = require('fs');
const vm = require('vm');
const data = JSON.parse(fs.readFileSync(0, 'utf8'));
const parent = {innerText: data.text, querySelector: () =>
  data.selected ? {selectedOptions: [{textContent: data.selected}]} : null};
const input = {parentElement: parent, getAttribute: () => 'fixture:0'};
const document = {querySelectorAll: () => [input]};
process.stdout.write(JSON.stringify(vm.runInNewContext(data.expression, {document})));
''')

    def evaluate(expression):
        result = subprocess.run([node, str(script)], input=json.dumps({
            'expression': expression, 'text': parent_text, 'selected': selected}),
            text=True, capture_output=True, check=True, timeout=10)
        return {'ok': True, 'result': json.loads(result.stdout)}

    actor, supervisor = kernel_page(kernel, 'https://shop.example')
    evaluate_runtime = supervisor.evaluate_runtime
    supervisor.evaluate_runtime = lambda expression: (evaluate(expression)
        if "querySelectorAll('[data-hermes-vault-slot]')" in expression
        else evaluate_runtime(expression))
    supervisor.controls = [{'index': 0, 'type': 'tel', 'name': 'mobile', 'label': 'Phone number',
                            'autocomplete': '', 'maxLength': 10, 'formIndex': 0}]
    fills = []

    secret_eval = native._eval_js_secret

    def fill(task, expression):
        assert task == kernel.cloud.native_task_id(actor)
        # Only fixture data reaches this secret-only path; the public result
        # must remain metadata. Check that national digits, not a truncated
        # international number, are used after the actual JS observation.
        assert json.dumps('9876543210') in expression
        assert json.dumps('+919876543210') not in expression
        fills.append(expression)
        return secret_eval(task, expression)

    monkeypatch.setattr(native, '_eval_js_secret', fill)
    values = {'phone_number': '+919876543210'}
    if country_code:
        values['country_code'] = country_code
    PersonalStore(service.private_home('TT', 'UA')).save('phone', values)
    if accepted:
        result = service.personal.fill(actor, origin='https://shop.example', fields=['phone'])
        assert result['success'] and result['filled_fields'] == 1
        assert '9876543210' not in json.dumps(result)
        assert len(fills) == 1
    else:
        with pytest.raises(AccessError, match='Inspect the website'):
            service.personal.fill(actor, origin='https://shop.example', fields=['phone'])
        assert not fills


