"""Opt-in model checks of production prompts with synthetic personal-info tools.

No actual vault values, browser execution, Slack messages or purchases are used.
"""
import argparse
import json
import os
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
LAB_HOME = ROOT / '.local/hermes-lab/home'
sys.path[:0] = [str(ROOT / 'hermes'), str(ROOT / 'runtime')]
os.environ['HERMES_HOME'] = str(LAB_HOME)

from agent.auxiliary_client import call_llm
from agent.prompt_builder import load_soul_md
from gateway.run import GatewayRunner, _profile_runtime_scope, _resolve_gateway_model, _resolve_runtime_agent_kwargs
from hermes_cli.plugins import discover_plugins, render_system_prompt_sections
from tools.registry import registry

CASES = ('saved_details', 'missing_phone', 'ambiguous_form', 'shared_handoff')
ORIGIN = 'https://shop.example'
VAULT_URL = 'https://vault.example.invalid/vault'


def replay(name, runtime, model, prompt, schemas):
    messages = [{'role': 'system', 'content': prompt + '\n\n'
                 'This is an offline evaluation: tool observations simulate website state; no real browser or purchase runs. '
                 'Current task is in ' + ('a shared Slack channel.' if name == 'shared_handoff' else 'the requester\'s private DM.') +
                 ' A cloud worker reported a delivery-location blocker at ' + ORIGIN +
                 '. The local delivery preview needs an address and contact phone; email is optional. No signup or payment is needed.'},
                {'role': 'user', 'content': 'Prepare my grocery cart for delivery at ' + ORIGIN +
                 ' and stop at the preview before ordering. Continue from the delivery-location blocker.'}]
    calls = []
    filled = set()
    form_failed = False
    form_recovered = False

    def handle(tool, args):
        nonlocal form_failed, form_recovered
        if tool == 'clanker_vault_list':
            if name == 'shared_handoff':
                return {'status': 'moved_to_private', 'private_results': False,
                        'next': 'The requester-isolated private worker continues automatically. End this turn. No credential form was sent.'}
            personal = {kind: {'saved': name != 'missing_phone' or kind != 'phone',
                              'summary': 'Saved for delivery and forms' if kind == 'address' else 'Ending 0101' if kind == 'phone' else 'a•••@example.invalid'}
                        for kind in ('address', 'phone', 'email')}
            return {'items': [], 'personal_info': personal, 'personal_info_url': VAULT_URL,
                    'next': 'Reuse required saved primaries locally; ask only for required unknowns via private Personal info.'}
        if tool == 'browser_exec':
            if form_failed:
                form_recovered = True
            return {'success': True, 'origin': ORIGIN, 'local_private_browser': True,
                    'observed': 'Intended delivery form open; address and phone required, email optional. ' +
                                ('Duplicate form closed; field ambiguity resolved. ' if form_recovered else '') +
                                'Filled kinds: ' + ', '.join(sorted(filled)) + '. No form submitted.',
                    'preview_ready': {'address', 'phone'} <= filled}
        if tool != 'clanker_personal_fill':
            raise AssertionError('Unexpected tool: ' + tool)
        assert args['origin'] == ORIGIN
        fields = args['fields']
        assert isinstance(fields, list) and fields
        if name == 'ambiguous_form' and not form_failed:
            form_failed = True
            return {'success': False, 'status': 409,
                    'error': 'The address fields are ambiguous. Leave only the intended form open.'}
        if form_failed and not form_recovered:
            return {'success': False, 'status': 409, 'error': 'Recover the duplicate form before retrying.'}
        if name == 'missing_phone' and 'phone' in fields:
            return {'status': 'personal_info_needed', 'missing': ['phone'],
                    'available_fields': [field for field in fields if field != 'phone'],
                    'vault_url': VAULT_URL,
                    'next': 'Fill available_fields separately. Request only the missing phone via private Personal info, then resume.'}
        filled.update(fields)
        return {'success': True, 'filled_fields': len(fields), 'origin': ORIGIN,
                'next': 'Requested personal details filled. Review and continue; no form submitted.'}

    tools = [{'type': 'function', 'function': schema} for schema in schemas]
    answer = ''
    for _ in range(8):
        response = call_llm(provider=runtime['provider'], model=model,
                            base_url=runtime.get('base_url'), api_key=runtime.get('api_key'),
                            api_mode=runtime.get('api_mode'), main_runtime=runtime,
                            messages=messages, tools=tools, timeout=45,
                            reasoning_config={'effort': 'low'})
        message = response.choices[0].message
        if not message.tool_calls:
            answer = message.content or ''
            break
        messages.append({'role': 'assistant', 'content': message.content or '', 'tool_calls': [
            {'id': call.id, 'type': 'function', 'function': {
                'name': call.function.name, 'arguments': call.function.arguments}}
            for call in message.tool_calls]})
        for call in message.tool_calls:
            args = json.loads(call.function.arguments)
            output = handle(call.function.name, args)
            calls.append({'tool': call.function.name, 'arguments': args, 'result': output})
            messages.append({'role': 'tool', 'tool_call_id': call.id, 'content': json.dumps(output)})
    names = [row['tool'] for row in calls]
    passed = bool(answer) and bool(names) and names[0] == 'clanker_vault_list'
    if name == 'shared_handoff':
        passed = passed and names == ['clanker_vault_list'] and '?' not in answer
    else:
        passed = passed and 'address' in filled and 'email' not in filled
        if name == 'missing_phone':
            passed = passed and 'phone' not in filled and 'phone' in answer.lower() and VAULT_URL in answer
            passed = passed and not any(phrase in answer.lower() for phrase in ('your address?', 'delivery address?', 'what address', 'what location'))
        else:
            passed = passed and 'phone' in filled and '?' not in answer
            if name == 'ambiguous_form':
                passed = passed and form_failed and form_recovered and names.count('clanker_personal_fill') >= 2
    return {'case': name, 'passed': passed, 'calls': calls, 'answer': answer,
            'filled_kinds': sorted(filled), 'fixture_only': True}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run-model', action='store_true', help='Use the configured subscription model with fixture-only tool handlers.')
    parser.add_argument('--output', type=Path, required=True, help='Save model/tool observations as JSON.')
    args = parser.parse_args()
    if not args.run_model:
        parser.error('--run-model is required to make model requests')
    with _profile_runtime_scope(LAB_HOME):
        discover_plugins()
        sections = render_system_prompt_sections({'platform': 'slack', 'profile_name': 'default'})
        assert {'clanker.execution', 'clanker.personal_info', 'clanker.browser', 'clanker.payments',
                'clanker.api_keys', 'clanker.browser_handoff', 'clanker.recall'} <= {section.id for section in sections}
        prompt = '\n\n'.join(part for part in (load_soul_md(home_override=LAB_HOME), GatewayRunner._load_ephemeral_system_prompt()) if part) + '\n\n' + '\n\n'.join(section.content for section in sections)
        schemas = [registry.get_schema(name) for name in ('clanker_vault_list', 'clanker_personal_fill')]
        assert all(schemas)
        schemas.append({'name': 'browser_exec', 'description': 'Inspect, navigate and recover this task\'s private LOCAL browser. No payment or form submission.',
                        'parameters': {'type': 'object', 'properties': {'code': {'type': 'string'}, 'session': {'type': 'string'}, 'timeout_s': {'type': 'integer'}},
                                       'required': ['code'], 'additionalProperties': False}})
        runtime = _resolve_runtime_agent_kwargs()
        if runtime['provider'] != 'openai-codex' or runtime['api_mode'] != 'codex_responses':
            raise RuntimeError('This probe requires the configured Codex subscription route.')
        model = runtime.get('model') or _resolve_gateway_model()
        observations = []
        for name in CASES:
            print(json.dumps({'case': name, 'stage': 'running'}), flush=True)
            observation = replay(name, runtime, model, prompt, schemas)
            observations.append(observation)
            print(json.dumps({'case': name, 'passed': observation['passed']}), flush=True)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps({'model': model, 'fixture_only': True, 'observations': observations}, indent=2) + '\n')
        if not all(row['passed'] for row in observations):
            raise SystemExit(1)


if __name__ == '__main__':
    main()
